        p.jsxs("div", { className: `p-4 sm:p-5 rounded-2xl ${periodBalance >= 0 ? "bg-slate-50 border-slate-300" : "bg-amber-50 border-amber-300"} border space-y-1 shadow-2xs`, children: [
          p.jsx("p", { className: "text-xs sm:text-sm font-bold text-slate-800", children: `${periodLabel} ${isBn ? "অবশিষ্ট ব্যালেন্স (হাতে আছে)" : "Remaining In Hand"}` }),
          p.jsx("p", { className: `text-xl sm:text-2xl font-black font-mono ${periodBalance >= 0 ? "text-emerald-700" : "text-rose-600"}`, children: (periodBalance < 0 ? "-" : "") + formatSum(periodBalance) }),
          p.jsx("p", { className: "text-xs text-slate-500 font-medium", children: periodBalance >= 0 ? (isBn ? "উদ্বৃত্ত জমা আছে" : "Surplus funds") : (isBn ? "ঘাটতি রয়েছে" : "Deficit") })
        ] })
